import bz2
import lzma
import zlib

_RAW = 0
_ZLIB = 1
_BZ2 = 2
_LZMA = 3


def enc(data):
    """Encode nonempty bytes, choosing the smallest lossless representation."""
    data = bytes(data)
    if not data:
        raise ValueError("enc expects a nonempty byte string")

    best = bytes((_RAW,)) + data
    candidates = (
        bytes((_ZLIB,)) + zlib.compress(data, 9),
        bytes((_BZ2,)) + bz2.compress(data, compresslevel=9),
        bytes((_LZMA,)) + lzma.compress(data, preset=9),
    )
    for candidate in candidates:
        if len(candidate) < len(best):
            best = candidate
    return best


def dec(payload):
    """Inverse of enc."""
    payload = bytes(payload)
    if not payload:
        raise ValueError("invalid encoded data")
    tag, body = payload[0], payload[1:]
    if tag == _RAW:
        if not body:
            raise ValueError("invalid raw representation")
        return body
    if tag == _ZLIB:
        return zlib.decompress(body)
    if tag == _BZ2:
        return bz2.decompress(body)
    if tag == _LZMA:
        return lzma.decompress(body)
    raise ValueError("unknown encoding")

import bz2
import lzma
import struct
import zlib

_RAW = 0
_ZLIB = 1
_BZ2 = 2
_LZMA = 3


def _hex_transform(data):
    """Pack long ASCII-hex lines, retaining all other bytes verbatim."""
    chunks = data.splitlines(keepends=True)
    if not chunks:
        return None
    out = bytearray(b"HX1")
    packed = 0
    for chunk in chunks:
        if chunk.endswith(b"\n"):
            line, ending = chunk[:-1], b"\n"
            if line.endswith(b"\r"):
                line, ending = line[:-1], b"\r\n"
        elif chunk.endswith(b"\r"):
            line, ending = chunk[:-1], b"\r"
        else:
            line, ending = chunk, b""
        if (len(line) >= 32 and len(line) % 2 == 0 and
                all(c in b"0123456789abcdefABCDEF" for c in line)):
            raw = bytes.fromhex(line.decode("ascii"))
            out.append(1)
            out.extend(struct.pack(">H", len(line)))
            out.extend(raw)
            out.append(len(ending))
            packed += 1
        else:
            out.append(0)
            out.extend(struct.pack(">I", len(chunk)))
            out.extend(chunk)
    if not packed:
        return None
    return bytes(out)


def _hex_inverse(data):
    if not data.startswith(b"HX1"):
        raise ValueError("invalid transformed data")
    pos = 3
    out = bytearray()
    while pos < len(data):
        tag = data[pos]
        pos += 1
        if tag == 0:
            if pos + 4 > len(data):
                raise ValueError("truncated transformed data")
            n = struct.unpack(">I", data[pos:pos + 4])[0]
            pos += 4
            out.extend(data[pos:pos + n])
            if pos + n > len(data):
                raise ValueError("truncated transformed data")
            pos += n
        elif tag == 1:
            if pos + 2 > len(data):
                raise ValueError("truncated transformed data")
            chars = struct.unpack(">H", data[pos:pos + 2])[0]
            pos += 2
            n = chars // 2
            if chars % 2 or pos + n + 1 > len(data):
                raise ValueError("truncated transformed data")
            out.extend(data[pos:pos + n].hex().encode("ascii"))
            pos += n
            ending = data[pos]
            pos += 1
            if ending == 1:
                out.extend(b"\n")
            elif ending == 2:
                out.extend(b"\r\n")
            elif ending == 3:
                out.extend(b"\r")
            elif ending != 0:
                raise ValueError("invalid line ending")
        else:
            raise ValueError("invalid transform record")
    return bytes(out)


def _compressed(data):
    return (
        zlib.compress(data, 9),
        bz2.compress(data, compresslevel=9),
        lzma.compress(data, preset=9),
    )


def enc(data):
    """Encode nonempty bytes, choosing the smallest lossless representation."""
    data = bytes(data)
    if not data:
        raise ValueError("enc expects a nonempty byte string")

    best = bytes((_RAW,)) + data
    for tag, body in enumerate(_compressed(data), 1):
        candidate = bytes((tag,)) + body
        if len(candidate) < len(best):
            best = candidate

    transformed = _hex_transform(data)
    if transformed is not None:
        for tag, body in enumerate(_compressed(transformed), 4):
            candidate = bytes((tag,)) + body
            if len(candidate) < len(best):
                best = candidate
    return best


def dec(payload):
    """Inverse of enc."""
    payload = bytes(payload)
    if not payload:
        raise ValueError("invalid encoded data")
    tag, body = payload[0], payload[1:]
    if tag == _RAW:
        if not body:
            raise ValueError("invalid raw representation")
        return body
    if tag in (_ZLIB, 4):
        result = zlib.decompress(body)
    elif tag in (_BZ2, 5):
        result = bz2.decompress(body)
    elif tag in (_LZMA, 6):
        result = lzma.decompress(body)
    else:
        raise ValueError("unknown encoding")
    return _hex_inverse(result) if tag >= 4 else result
